const countryByCode = new Map(countries.map((country) => [country.code, country]));

export const opportunities: LocalOpportunity[] = specs.map((spec) => {
  const country = countryByCode.get(spec.countryCode)!;
  return {
    ...spec,
    countryName: country.name,
    countryNameAr: country.nameAr,
    flag: country.flag,
    category: { ar: spec.categoryAr, en: spec.categoryEn },
    overview: { ar: spec.overviewAr, en: spec.overviewEn },
    financialBenefits: { ar: spec.benefitsAr, en: spec.benefitsEn },
    eligibilityCriteria: { ar: spec.eligibilityAr, en: spec.eligibilityEn },
    requiredDocuments: { ar: spec.documentsAr, en: spec.documentsEn },
    applicationSteps: { ar: spec.stepsAr, en: spec.stepsEn },
  };
});

export const localCountries = countries.map((country) => ({
  ...country,
  opportunityCount: opportunities.filter((item) => item.countryCode === country.code).length,
  scholarshipCount: opportunities.filter((item) => item.countryCode === country.code && item.type === "scholarship").length,
  migrationCount: opportunities.filter((item) => item.countryCode === country.code && item.type === "migration").length,
}));

export function getLocalOpportunity(id: number) {
  return opportunities.find((opportunity) => opportunity.id === id);
}

export function getLocalCountry(code: string) {
  const country = localCountries.find((item) => item.code === code.toUpperCase());
  if (!country) return undefined;
  return {
    ...country,
    description: `دليل رسمي للمنح والقبول ومسارات العمل في ${country.nameAr}.`,
    opportunities: opportunities.filter((item) => item.countryCode === country.code),
  };
}